// Some portions generated by Claude
package org.eclipse.rdf4j.sail.memory;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.StringReader;
import java.util.ArrayList;
import java.util.List;

import org.eclipse.rdf4j.model.Literal;
import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.QueryResults;
import org.eclipse.rdf4j.query.TupleQueryResult;
import org.eclipse.rdf4j.repository.RepositoryConnection;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.rio.RDFFormat;
import org.junit.jupiter.api.AfterAll;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.Test;

/**
 * End-to-end SPARQL tests for the {@code agg:} extension aggregates on a {@link MemoryStore}.
 */
public class ExtensionAggregateSparqlTest {

	private static final String PREFIXES = "PREFIX agg: <http://rdf4j.org/aggregate#>\n"
			+ "PREFIX arrf: <http://rdf4j.org/function/array#>\n" + "PREFIX ex: <http://example.org/>\n";

	private static SailRepository repository;

	@BeforeAll
	static void setUp() throws Exception {
		repository = new SailRepository(new MemoryStore());
		String data = "@prefix ex: <http://example.org/> .\n"
				+ "ex:e1 ex:dept ex:sales ; ex:salary 10 ; ex:age 30 ; ex:active true .\n"
				+ "ex:e2 ex:dept ex:sales ; ex:salary 30 ; ex:age 40 ; ex:active true .\n"
				+ "ex:e3 ex:dept ex:sales ; ex:salary 20 ; ex:age 35 ; ex:active false .\n"
				+ "ex:e4 ex:dept ex:eng ; ex:salary 50 ; ex:age 50 ; ex:active true .\n"
				+ "ex:e5 ex:dept ex:eng ; ex:salary 70 ; ex:age 60 ; ex:active true .\n";
		try (RepositoryConnection conn = repository.getConnection()) {
			conn.add(new StringReader(data), "", RDFFormat.TURTLE);
		}
	}

	@AfterAll
	static void tearDown() {
		repository.shutDown();
	}

	private static List<BindingSet> query(String query) {
		try (RepositoryConnection conn = repository.getConnection();
				TupleQueryResult result = conn.prepareTupleQuery(PREFIXES + query).evaluate()) {
			return new ArrayList<>(QueryResults.asList(result));
		}
	}

	private static String str(BindingSet bs, String var) {
		return bs.getValue(var).stringValue();
	}

	@Test
	void unaryAggregatesPerGroup() {
		List<BindingSet> rows = query("SELECT ?dept (agg:median(?salary) AS ?median) (agg:mode(?active) AS ?mode)"
				+ " (agg:countIf(?active) AS ?actives) (agg:boolAnd(?active) AS ?all) (agg:boolOr(?active) AS ?any)"
				+ " (agg:arrayAgg(?salary) AS ?arr) WHERE { ?e ex:dept ?dept ; ex:salary ?salary ; ex:active ?active }"
				+ " GROUP BY ?dept ORDER BY ?dept");
		assertThat(rows).hasSize(2);
		BindingSet eng = rows.get(0);
		assertThat(str(eng, "dept")).endsWith("eng");
		assertThat(str(eng, "median")).isEqualTo("60");
		assertThat(str(eng, "mode")).isEqualTo("true");
		assertThat(str(eng, "actives")).isEqualTo("2");
		assertThat(str(eng, "all")).isEqualTo("true");
		BindingSet sales = rows.get(1);
		assertThat(str(sales, "median")).isEqualTo("20");
		assertThat(str(sales, "actives")).isEqualTo("2");
		assertThat(str(sales, "all")).isEqualTo("false");
		assertThat(str(sales, "any")).isEqualTo("true");
		assertThat(((Literal) sales.getValue("arr")).getLabel()).matches("\\[(10|20|30),(10|20|30),(10|20|30)\\]");
	}

	@Test
	void naryAggregates() {
		List<BindingSet> rows = query("SELECT (agg:percentileCont(?salary, 0.5) AS ?p50)"
				+ " (agg:percentileDisc(?salary, 0.5) AS ?d50) (agg:corr(?salary, ?age) AS ?corr)"
				+ " (agg:covarPop(?salary, ?age) AS ?cp) (agg:covarSamp(?salary, ?age) AS ?cs)"
				+ " (agg:argMax(?e, ?salary) AS ?top) (agg:argMin(?e, ?salary) AS ?bottom)"
				+ " (agg:approxQuantile(?salary, 0.5) AS ?aq) (agg:approxCountDistinct(?dept) AS ?depts)"
				+ " WHERE { ?e ex:dept ?dept ; ex:salary ?salary ; ex:age ?age }");
		assertThat(rows).hasSize(1);
		BindingSet bs = rows.get(0);
		assertThat(str(bs, "p50")).isEqualTo("30");
		assertThat(str(bs, "d50")).isEqualTo("30");
		assertThat(((Literal) bs.getValue("corr")).doubleValue()).isGreaterThan(0.95);
		assertThat(((Literal) bs.getValue("cp")).doubleValue()).isGreaterThan(0);
		assertThat(((Literal) bs.getValue("cs")).doubleValue())
				.isGreaterThan(((Literal) bs.getValue("cp")).doubleValue());
		assertThat(str(bs, "top")).endsWith("e5");
		assertThat(str(bs, "bottom")).endsWith("e1");
		assertThat(((Literal) bs.getValue("aq")).doubleValue()).isBetween(20.0, 50.0);
		assertThat(str(bs, "depts")).isEqualTo("2");
	}

	@Test
	void distinctAndHistogramAndUnnestRoundTrip() {
		List<BindingSet> rows = query("SELECT (agg:median(DISTINCT ?v) AS ?m) (agg:histogram(?v) AS ?h) WHERE {"
				+ " VALUES ?v { 1 1 1 5 } }");
		assertThat(str(rows.get(0), "m")).isEqualTo("3");
		assertThat(str(rows.get(0), "h")).isEqualTo("[{\"value\":1,\"count\":3},{\"value\":5,\"count\":1}]");
		rows = query("SELECT ?dept ?e WHERE { { SELECT ?dept (agg:arrayAgg(?emp) AS ?arr) WHERE {"
				+ " ?emp ex:dept ?dept } GROUP BY ?dept } ?arr arrf:unnest ?e } ORDER BY ?dept ?e");
		assertThat(rows).hasSize(5);
		assertThat(str(rows.get(0), "e")).endsWith("e4");
		assertThat(str(rows.get(4), "e")).endsWith("e3");
	}

	@Test
	void emptyGroupsLeaveAggregatesUnbound() {
		List<BindingSet> rows = query("SELECT (agg:median(?x) AS ?m) (agg:boolAnd(?x) AS ?b) (agg:first(?x) AS ?f)"
				+ " (agg:countIf(?x) AS ?c) WHERE { OPTIONAL { ?s ex:nothing ?x } }");
		assertThat(rows).hasSize(1);
		assertThat(rows.get(0).hasBinding("m")).isFalse();
		assertThat(rows.get(0).hasBinding("b")).isFalse();
		assertThat(rows.get(0).hasBinding("f")).isFalse();
		assertThat(str(rows.get(0), "c")).isEqualTo("0");
	}
}
